// Joins the base word data (characters, batch-*.js, convos, levels, pack list, KK) into js/data/base.js,
// so the app downloads one file instead of 18. Run after changing any of those files:
//   node scripts/build-bundle.mjs           write js/data/base.js
//   node scripts/build-bundle.mjs --check   exit 1 if js/data/base.js is out of date (nothing is written)
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
const dataDir = path.join(root, "js", "data");
const OUT = "js/data/base.js";

const batches = fs.readdirSync(dataDir)
  .filter((f) => /^batch-\d+\.js$/.test(f))
  .sort((a, b) => parseInt(a.match(/\d+/)[0]) - parseInt(b.match(/\d+/)[0]))
  .map((f) => "js/data/" + f);
// Same order the separate <script> tags used to load in.
const FILES = ["js/data/characters.js", ...batches, "js/data/convos.js", "js/data/levels.js", "js/data/packs/index.js", "js/data/kk.js"];

const read = (f) => fs.readFileSync(path.join(root, f), "utf8").replace(/\r\n/g, "\n");
const bundle =
  "// Generated by scripts/build-bundle.mjs. Do not edit by hand: edit the files below, then run it again.\n" +
  "// " + FILES.join(", ") + "\n" +
  FILES.map((f) => "\n// ---- " + f + " ----\n" + read(f).replace(/\s*$/, "\n") + ";\n").join("");

if (process.argv.includes("--check")) {
  const current = fs.existsSync(path.join(root, OUT)) ? read(OUT) : "";
  if (current !== bundle) {
    console.error(OUT + " is out of date. Run: node scripts/build-bundle.mjs");
    process.exit(1);
  }
  console.log(OUT + " is up to date (" + FILES.length + " files).");
} else {
  fs.writeFileSync(path.join(root, OUT), bundle);
  console.log("Wrote " + OUT + " from " + FILES.length + " files (" + Math.round(bundle.length / 1024) + " KB).");
}
